get_seo_configuration.code:
use WebCommander\Sdk\Resources\Settings\SeoConfiguration\SeoConfiguration;

$response = SeoConfiguration::getSeoConfiguration($client);

$seo = $response->map['seo_configuration'];
echo 'store name: ', $seo['global_store_settings']['store_name'], PHP_EOL;
foreach ($seo['url_settings']['redirects']['items'] as $redirect) {
    echo $redirect['source_url'], ' -> ', $redirect['destination_url'], PHP_EOL;
}

put_seo_configuration.code:
use WebCommander\Sdk\Resources\Settings\SeoConfiguration\SeoConfiguration;

$response = SeoConfiguration::putSeoConfiguration($client, [
    'seo_configuration' => [
        'url_settings' => ['regenerate_url_on_item_update' => true, 'auto_redirect_on_url_change' => true],
    ],
]);

$urlSettings = $response->map['seo_configuration']['url_settings'];
echo 'regenerate: ', $urlSettings['regenerate_url_on_item_update'] ? 'on' : 'off', PHP_EOL;
echo 'auto redirect: ', $urlSettings['auto_redirect_on_url_change'] ? 'on' : 'off', PHP_EOL;

get_seo_configuration_section.code:
use WebCommander\Sdk\Resources\Settings\SeoConfiguration\SeoConfiguration;

$response = SeoConfiguration::getSeoConfigurationSection($client, 'url_settings');

$urlSettings = $response->map['url_settings'];
echo 'auto redirect: ', $urlSettings['auto_redirect_on_url_change'] ? 'on' : 'off', PHP_EOL;
echo count($urlSettings['redirects']['items']), ' redirects', PHP_EOL;

put_seo_configuration_section.code:
use WebCommander\Sdk\Resources\Settings\SeoConfiguration\SeoConfiguration;

$response = SeoConfiguration::putSeoConfigurationSection($client, 'url_settings', [
    'url_settings' => ['regenerate_url_on_item_update' => true, 'auto_redirect_on_url_change' => true],
]);

$urlSettings = $response->map['url_settings'];
echo 'regenerate: ', $urlSettings['regenerate_url_on_item_update'] ? 'on' : 'off', PHP_EOL;
echo 'auto redirect: ', $urlSettings['auto_redirect_on_url_change'] ? 'on' : 'off', PHP_EOL;

get_seo_configuration_document_root.code:
use WebCommander\Sdk\Resources\Settings\SeoConfiguration\SeoConfiguration;

$response = SeoConfiguration::getSeoConfigurationDocumentRoot($client, ['limit' => 100]);

foreach ($response->map['items'] as $file) {
    echo $file['config_key'], ' ', $file['file_name'], PHP_EOL;
}
echo $response->map['pagination']['total'], ' files', PHP_EOL;

get_seo_configuration_redirects.code:
use WebCommander\Sdk\Resources\Settings\SeoConfiguration\SeoConfiguration;

$response = SeoConfiguration::getSeoConfigurationRedirects($client, ['limit' => 100]);

foreach ($response->map['items'] as $redirect) {
    echo $redirect['id'], ' ', $redirect['source_url'], ' -> ', $redirect['destination_url'], PHP_EOL;
}
echo $response->map['pagination']['has_next'] ? 'more to fetch' : 'all fetched', PHP_EOL;
